import { listAssets } from './registry';
import { ART } from './spec';
import type { AssetDef } from './types';
import { sheetDefs, sheetSize } from './sheets';

/**
 * Bundled PNG artwork (all local files, bundled by Vite; nothing is fetched from a URL):
 *  - images/<asset id>.png   sprites that replace an asset's procedural drawing (products, props, people…)
 *  - sheets/<sheet id>.png   character sprite sheets (see sheets.ts for the layout)
 *  - textures/<terrain>.png  2×2-cell terrain textures used by the ground painter
 * The files are generated by `npm run art:export` (src/tools/exportArt.ts) and can be repainted by hand.
 * A missing, broken or wrongly sized file is rejected and the procedural art is used instead.
 */
const glob = (pick: () => Record<string, string>): Record<string, string> => {
  try {
    return pick();
  } catch {
    return {};
  }
};
const imageFiles = glob(() => import.meta.glob('./images/*.png', { eager: true, query: '?url', import: 'default' }) as Record<string, string>);
const sheetFiles = glob(() => import.meta.glob('./sheets/*.png', { eager: true, query: '?url', import: 'default' }) as Record<string, string>);
const textureFiles = glob(() => import.meta.glob('./textures/*.png', { eager: true, query: '?url', import: 'default' }) as Record<string, string>);

const baseName = (p: string) => p.replace(/^.*\//, '').replace(/\.png$/, '');

export function bundledImageIds(): string[] {
  return Object.keys(imageFiles).map(baseName);
}

/** Terrain textures are 2×2 cells of this many pixels each. */
export const TEXTURE_CELL = 64;

const loaded = new Map<string, HTMLImageElement>();
const sheets = new Map<string, HTMLImageElement>();
const textures = new Map<string, HTMLImageElement>();
const rejected = new Map<string, string>();
let version = 0;

/** Sprite PNGs cover the asset box plus its transparent padding; the aspect must match within ±3%. */
export function imageFits(def: AssetDef, w: number, h: number): boolean {
  if (!(w > 0 && h > 0)) return false;
  const a = w / h;
  const b = (def.size.w + ART.padding * 2) / (def.size.h + ART.padding * 2);
  return Math.abs(a - b) / b <= 0.03;
}

function load(url: string): Promise<HTMLImageElement | null> {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => resolve(null);
    img.src = url;
  });
}

export function loadBundledImages(onProgress?: (done: number, total: number) => void): Promise<void> {
  if (typeof Image === 'undefined') return Promise.resolve();
  const byId = new Map(listAssets().map((a) => [a.id, a]));
  const sheetKinds = new Map(sheetDefs().map((d) => [d.id, d.kind]));
  const jobs: [string, string, (img: HTMLImageElement) => void][] = [];
  for (const [path, url] of Object.entries(imageFiles)) {
    const id = baseName(path);
    const def = byId.get(id);
    if (!def) {
      rejected.set(`images/${id}`, 'no asset with this id');
      continue;
    }
    jobs.push([`images/${id}`, url, (img) => (imageFits(def, img.naturalWidth, img.naturalHeight) ? loaded.set(id, img) : rejected.set(`images/${id}`, `size ${img.naturalWidth}×${img.naturalHeight} does not fit ${def.size.w}×${def.size.h} (+padding)`))]);
  }
  for (const [path, url] of Object.entries(sheetFiles)) {
    const id = baseName(path);
    const kind = sheetKinds.get(id);
    if (!kind) {
      rejected.set(`sheets/${id}`, 'no sheet with this id');
      continue;
    }
    const want = sheetSize(kind);
    jobs.push([`sheets/${id}`, url, (img) => (img.naturalWidth === want.w && img.naturalHeight === want.h ? sheets.set(id, img) : rejected.set(`sheets/${id}`, `size ${img.naturalWidth}×${img.naturalHeight}, expected ${want.w}×${want.h}`))]);
  }
  for (const [path, url] of Object.entries(textureFiles)) {
    const id = baseName(path);
    jobs.push([`textures/${id}`, url, (img) => (img.naturalWidth === TEXTURE_CELL * 2 && img.naturalHeight === TEXTURE_CELL * 2 ? textures.set(id, img) : rejected.set(`textures/${id}`, 'expected 128×128'))]);
  }
  let done = 0;
  return Promise.all(
    jobs.map(async ([key, url, accept]) => {
      const img = await load(url);
      if (img) accept(img);
      else rejected.set(key, 'failed to decode');
      onProgress?.(++done, jobs.length);
    }),
  ).then(() => {
    version++;
    if (rejected.size && import.meta.env?.DEV) console.warn('[assets] rejected images', Object.fromEntries(rejected));
  });
}

export function imageFor(id: string): HTMLImageElement | undefined {
  return loaded.get(id);
}

export function sheetImage(id: string): HTMLImageElement | undefined {
  return sheets.get(id);
}

export function textureImage(terrainId: string): HTMLImageElement | undefined {
  return textures.get(terrainId);
}

/** Increments whenever a batch of files finishes loading (caches built from art can re-bake). */
export function artVersion(): number {
  return version;
}

export function imageDiagnostics() {
  return {
    files: { images: Object.keys(imageFiles).length, sheets: Object.keys(sheetFiles).length, textures: Object.keys(textureFiles).length },
    loaded: { images: loaded.size, sheets: sheets.size, textures: textures.size },
    rejected: Object.fromEntries(rejected),
  };
}
